$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type @"
using System;using System.Runtime.InteropServices;public class S360AuditLang2{[DllImport("user32.dll")]public static extern bool SetForegroundWindow(IntPtr hWnd);[DllImport("user32.dll")]public static extern bool SetCursorPos(int X,int Y);[DllImport("user32.dll")]public static extern void mouse_event(uint flags,uint dx,uint dy,uint data,UIntPtr extra);}
"@
function Get-AppWindow{$root=[System.Windows.Automation.AutomationElement]::RootElement;$wins=$root.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);return $wins|Where-Object {$_.Current.Name -like '*Society360*Google Chrome'}|Select-Object -First 1}
$w=Get-AppWindow;if(!$w){throw 'Society360 Chrome window missing'};$null=[S360AuditLang2]::SetForegroundWindow([IntPtr]$w.Current.NativeWindowHandle);$codes=@('en','hi','mr','gu','kn','ta');$results=@()
for($i=0;$i -lt 6;$i++){$w=Get-AppWindow;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$combo=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::ComboBox}|Sort-Object {$_.Current.BoundingRectangle.Y}|Select-Object -First 1;if(!$combo){throw 'Language selector missing'};$ep=$combo.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern);if($ep.Current.ExpandCollapseState -eq [System.Windows.Automation.ExpandCollapseState]::Expanded){$ep.Collapse();Start-Sleep -Milliseconds 80};$ep.Expand();Start-Sleep -Milliseconds 120;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$opts=@($all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::ListItem -and $_.Current.Name});if($opts.Count -ne 6){throw ('Expected 6 language options, found '+$opts.Count)};$opt=$opts[$i];try{$opt.GetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern).Select()}catch{$r=$opt.Current.BoundingRectangle;if($r.Width -le 0 -or $r.Height -le 0){throw ('Language option not visible at index '+$i)};[S360AuditLang2]::SetCursorPos([int]($r.X+$r.Width/2),[int]($r.Y+$r.Height/2))|Out-Null;[S360AuditLang2]::mouse_event(2,0,0,0,[UIntPtr]::Zero);[S360AuditLang2]::mouse_event(4,0,0,0,[UIntPtr]::Zero)};Start-Sleep -Milliseconds 650;$w=Get-AppWindow;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$edit=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and $_.Current.Name -ne 'Address and search bar' -and $_.Current.Name}|Select-Object -First 1;$searchName=if($edit){$edit.Current.Name}else{''};$stillEnglish=$searchName -eq 'Search approver / entity / decision';$results+=([pscustomobject]@{languageCode=$codes[$i];labelDetected=[bool]$searchName;stillEnglish=$stillEnglish});Write-Output ('LANG='+$codes[$i]+'|LABEL='+[bool]$searchName+'|STILL_ENGLISH='+$stillEnglish)}
$w=Get-AppWindow;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$combo=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::ComboBox}|Sort-Object {$_.Current.BoundingRectangle.Y}|Select-Object -First 1;$ep=$combo.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern);if($ep.Current.ExpandCollapseState -eq [System.Windows.Automation.ExpandCollapseState]::Expanded){$ep.Collapse();Start-Sleep -Milliseconds 80};$ep.Expand();Start-Sleep -Milliseconds 120;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$opts=@($all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::ListItem -and $_.Current.Name});$opts[0].GetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern).Select();Start-Sleep -Milliseconds 500;if(($results|Where-Object {$_.languageCode -ne 'en' -and (!$_.labelDetected -or $_.stillEnglish)}).Count -gt 0){throw 'At least one non-English audit search label did not update'};Write-Output 'LANGUAGE_TEST=PASS; English restored'
